        <meshBasicMaterial />
      </mesh>
    </>
  );
};

const Scene = () => {
  return (
    <Canvas dpr={[1, 2]}>
      <Caustics />
      <OrbitControls />
      <PerspectiveCamera makeDefault position={[15, 15, 15]} fov={65} />
      <Environment
