    }
  });

  useFrame((state) => {
    const { camera } = state;
    kuwaharaPassRef.current.kernelSize = kernelSize;
    kuwaharaPassRef.current.enabled = enabled;
    camera.lookAt(0, 0, 0);
  });

  return (
