export const permute = /*@__PURE__*/ Fn(([x]) => {
  return mod(x.mul(34.0).add(1.0).mul(x), 289.0);
});

export const taylorInvSqrt = /*@__PURE__*/ Fn(
  ([r]) => {
    return sub(1.79284291400159, mul(0.85373472095314, r));
