  const Pi0 = floor(P);

  // Integer part for indexing

  const Pi1 = Pi0.add(vec3(1.0));

  // Integer part + 1

  Pi0.assign(mod(Pi0, 289.0));
  Pi1.assign(mod(Pi1, 289.0));
  const Pf0 = fract(P);

