  const Pf1 = Pf0.sub(vec3(1.0));

  // Fractional part - 1.0

  const ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  const iy = vec4(Pi0.yy, Pi1.yy);
  const iz0 = Pi0.zzzz;
  const iz1 = Pi1.zzzz;
  const ixy = permute(permute(ix).add(iy));
  const ixy0 = permute(ixy.add(iz0));
  const ixy1 = permute(ixy.add(iz1));
