      >
        <icosahedronGeometry args={[0.3, 16]} />
        <meshPhongMaterial
          key={uuidv4()}
          colorNode={nodes.colorNode}
          emissive={new THREE.Color('white').multiplyScalar(0.15)}
          shininess={400.0}
          positionNode={nodes.positionNode}
        />
      </instancedMesh>
    </>
  );
};

const Scene = () => {
