        spawnPos: vec3f,
        offsetPos: vec3f,
        uvCoord: vec2f
      ) -> vec4f {
        let color = vec3f(0.24, 0.43, 0.96);
        let distanceToCenter = min(
          distance(spawnPos + offsetPos, vec3f(0.0, 0.0, 0.0)),
