        let distColor = mix(
          vec3f(0.97, 0.7, 0.45),
          color,
          distanceToCenter * 0.4
        );

        let fillMask = 1.0 - strength * 2.0;
        let finalColor = mix(vec3f(0.0), distColor, fillMask);

