  vNormal = normalMatrix * displacedNormal;
  vPosition = (modelViewMatrix * vec4(displacedPosition, 1.0)).xyz;

  gl_Position = projectionMatrix * modelViewMatrix * vec4(displacedPosition, 1.0);
}

