        videoTexture,
        videoUvScaleX,
        videoUvScaleY,
      }),
    [
      detectionHeight,
      detectionWidth,
      resources,
      shaderUniforms,
      videoTexture,
      videoUvScaleX,
      videoUvScaleY,
    ],
  );

  const outputNode = useMemo(
    () =>
      createOutputNode({
        effectType: shaderUniforms.effectType,
        maxBlobs: MAX_BLOBS,
        resources,
        segmentType: shaderUniforms.segmentType,
        targetAspect,
        time: shaderUniforms.time,
        videoTexture,
        videoUvScaleX,
        videoUvScaleY,
      }),
    [
      resources,
      targetAspect,
      videoTexture,
      videoUvScaleX,
      videoUvScaleY,
    ],
  );

  useEffect(() => {
    const postProcessing = new THREE.PostProcessing(gl);
    postProcessing.outputNode = outputNode;
    postProcessingRef.current = postProcessing;

    return () => {
      postProcessingRef.current = null;
    };
  }, [gl, outputNode]);

  useEffect(() => {
    hasPreviousFrameRef.current = false;
    currentBufferIndexRef.current = 0;
    shaderUniforms.hasPreviousFrame.value = false;

    return () => {
      resources.stateTextures.forEach((stateTexture) => {
        stateTexture.dispose();
      });
    };
  }, [resources, shaderUniforms]);

  useFrame((state) => {
    const computeIndex = currentBufferIndexRef.current;
    shaderUniforms.effectType.value = effectType;
    shaderUniforms.hasPreviousFrame.value = hasPreviousFrameRef.current;
    shaderUniforms.segmentType.value = segmentType;
    shaderUniforms.time.value = state.clock.elapsedTime;

    gl.compute(computeMotionNodes[computeIndex]);
    gl.compute(computeBlobNodes[computeIndex]);

    if (postProcessingRef.current) {
      gl.clear();
      postProcessingRef.current.render();
    }

    hasPreviousFrameRef.current = true;
    currentBufferIndexRef.current = 1 - currentBufferIndexRef.current;
  }, 1);

  return null;
};

const App = () => (
  <>
    <Canvas
      dpr={[1, 1.5]}
      gl={async (props) => {
        const renderer = new THREE.WebGPURenderer(props);
        await renderer.init();
        return renderer;
      }}
    >
      <Suspense fallback={null}>
        <MotionBoxes />
      </Suspense>
    </Canvas>
    <Leva collapsed={false} />
  </>
);

export default App;

