        target={[0, PLANET.planetRadius + 2, 0]}
        minDistance={10}
        maxDistance={50000}
        enablePan={true}
        enableZoom={true}
        enableRotate={true}
      />
    </>
  );
};

const Scene = () => (
  <>
    <Canvas
      shadows
      gl={{
        alpha: true,
        logarithmicDepthBuffer: true,
        preserveDrawingBuffer: true,
      }}
      dpr={[1, 1.5]}
    >
      <Suspense>
